-- Real historical agro-weather dataset for Điện Biên, collected from NASA POWER.
-- Coordinates: 21.386 N, 103.016 E. Period: 2025-01-01 through 2025-12-31.
create table if not exists public.weather_observations (
  id uuid primary key default gen_random_uuid(), observed_date date not null,
  latitude double precision not null, longitude double precision not null,
  temperature_avg_c double precision, temperature_max_c double precision, temperature_min_c double precision,
  precipitation_mm double precision, relative_humidity_pct double precision,
  source text not null, source_url text not null, collected_at timestamptz not null default now(),
  unique(observed_date, latitude, longitude, source)
);
on conflict (observed_date, latitude, longitude, source) do update set temperature_avg_c=excluded.temperature_avg_c, temperature_max_c=excluded.temperature_max_c, temperature_min_c=excluded.temperature_min_c, precipitation_mm=excluded.precipitation_mm, relative_humidity_pct=excluded.relative_humidity_pct, collected_at=now();
create index if not exists idx_weather_observations_date on public.weather_observations (observed_date desc);
create index if not exists idx_weather_observations_location on public.weather_observations (latitude, longitude, observed_date desc);
